# NOTICE: Generated by Claude (LLM). Review before relying on it.
"""Five label layouts for frame 4 (4-estimates) of the training-cost chart.

Each point gets two labels: its cost, centered directly above or below the dot (past the end
of a range bar), and its model name in parentheses, placed wherever it fits. Reuses data,
colors, and axes from docs/assets/llms/training-cost/make_figures.py; writes v1..v5 SVGs here.

    python3 sandbox/training-cost-labels/label_variants.py
"""
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
SRC = HERE.parents[1] / "docs/assets/llms/training-cost"
sys.path.insert(0, str(SRC))
import make_figures as mf  # noqa: E402
import matplotlib.pyplot as plt  # noqa: E402
from matplotlib.legend_handler import HandlerTuple  # noqa: E402

GAP, LINE = 7, 15  # points from dot/bar end to a name label; one text line
COST_GAP = 3  # points from dot/bar end to the cost label: about half the visible gap at GAP
MODEL_SIZE, COST_SIZE = 11.5, 12.5

# Model-label spots, as (anchor, dx, dy, ha, va) in points from the dot ("mid") or a bar end.
SPOT = {
    "r": ("mid", 9, 0, "left", "center"),
    "l": ("mid", -9, 0, "right", "center"),
    "ar": ("hi", 7, 3, "left", "bottom"),
    "al": ("hi", -7, 3, "right", "bottom"),
    "br": ("lo", 7, -3, "left", "top"),
    "bl": ("lo", -7, -3, "right", "top"),
}

# Megatron-Turing NLG sits between GPT-3 and Gopher, so its long name goes up and left:
# level with its cost label, or one line higher when GPT-3's cost is above its dot.
MEG_INLINE = ("hi", -22, GAP, "right", "bottom")
MEG_HIGH = ("hi", 18, COST_GAP + LINE, "right", "bottom")

# Per variant: model -> (cost side "a"/"b", model spot). Spot "a"/"b" puts the name
# centered above/below, past the cost label when it is on the same side.
VARIANTS = {
    "v1-follow-edit": {  # sides taken from the hand-edited 4-estimates.svg
        "T2T big": ("b", "a"), "ELMo": ("b", "r"), "BERT base": ("a", "r"), "GPT-2": ("a", "a"),
        "NAS": ("b", "l"), "GPT-3": ("b", "r"), "Megatron-Turing NLG": ("a", MEG_INLINE),
        "Gopher": ("b", "r"), "BLOOM": ("b", "r"), "PaLM": ("a", "r"), "GPT-4": ("b", "l"),
        "Gemini Ultra": ("a", "l"), "Llama 3.1 405B": ("a", "r"), "DeepSeek-V3": ("b", "l"),
        "DeepSeek-R1": ("b", "l"), "Grok 3": ("a", "l"),
    },
    "v2-cost-above": {  # cost above unless a neighbor is in the way; name beside
        "T2T big": ("a", "b"), "ELMo": ("a", "r"), "BERT base": ("a", "r"), "GPT-2": ("a", "r"),
        "NAS": ("a", "l"), "GPT-3": ("a", "b"), "Megatron-Turing NLG": ("a", MEG_HIGH),
        "Gopher": ("b", "r"), "BLOOM": ("b", "r"), "PaLM": ("a", "r"), "GPT-4": ("b", "r"),
        "Gemini Ultra": ("a", "l"), "Llama 3.1 405B": ("a", "r"), "DeepSeek-V3": ("a", "r"),
        "DeepSeek-R1": ("a", "l"), "Grok 3": ("a", "l"),
    },
    "v3-cost-below": {  # cost below unless a neighbor is in the way; name beside
        "T2T big": ("b", "a"), "ELMo": ("b", "r"), "BERT base": ("a", "r"), "GPT-2": ("b", "r"),
        "NAS": ("b", "l"), "GPT-3": ("b", "l"), "Megatron-Turing NLG": ("a", MEG_INLINE),
        "Gopher": ("b", "r"), "BLOOM": ("b", "r"), "PaLM": ("b", "r"), "GPT-4": ("b", "l"),
        "Gemini Ultra": ("a", "l"), "Llama 3.1 405B": ("b", "r"), "DeepSeek-V3": ("b", "r"),
        "DeepSeek-R1": ("b", "l"), "Grok 3": ("b", "l"),
    },
    "v4-stacked": {  # name one line past the cost, same side: a two-line label
        "T2T big": ("a", "a"), "ELMo": ("b", "b"), "BERT base": ("a", "a"), "GPT-2": ("a", "a"),
        "NAS": ("b", "b"), "GPT-3": ("b", "b"), "Megatron-Turing NLG": ("a", "a"),
        "Gopher": ("b", "b"), "BLOOM": ("b", "b"), "PaLM": ("b", "b"), "GPT-4": ("b", "b"),
        "Gemini Ultra": ("a", "a"), "Llama 3.1 405B": ("b", "b"), "DeepSeek-V3": ("a", "a"),
        "DeepSeek-R1": ("b", "b"), "Grok 3": ("a", "a"),
    },
    "v5-split": {  # cost on one side, name on the other, unless a neighbor is in the way
        "T2T big": ("a", "b"), "ELMo": ("b", "r"), "BERT base": ("a", "b"), "GPT-2": ("a", "b"),
        "NAS": ("a", "b"), "GPT-3": ("a", "b"), "Megatron-Turing NLG": ("a", MEG_HIGH),
        "Gopher": ("b", "r"), "BLOOM": ("b", "r"), "PaLM": ("a", "b"), "GPT-4": ("b", "l"),
        "Gemini Ultra": ("a", "l"), "Llama 3.1 405B": ("a", "b"), "DeepSeek-V3": ("a", "b"),
        "DeepSeek-R1": ("a", "b"), "Grok 3": ("a", "b"),
    },
}


def label(ax, x, y, dx, dy, text, color, size, ha, va):
    ax.annotate(text, (x, y), xytext=(dx, dy), textcoords="offset points", ha=ha, va=va,
                fontsize=size, color=color)


def frame(d, spec, name):
    show = {"strubell", "reported", "estimate"}
    fig = plt.figure(figsize=mf.SIZE)
    ax = fig.add_axes(mf.AX)
    for m in mf.LABELS:
        r = d[m]
        x = r["year"] + mf.JITTER.get(m, 0)
        lo, hi = r["cost_low_usd"], r["cost_high_usd"]
        mid = (lo * hi) ** 0.5
        c = mf.BRAND[r["developer"]]
        if lo != hi:
            ax.plot([x, x], [lo, hi], color=c, lw=2, solid_capstyle="round", zorder=2)
        filled = mf.group(r) == "reported"
        ax.plot(x, mid, "o", ms=10, mfc=c if filled else "white", mec=c, mew=2, zorder=3)
        # A bar end sits at lo/hi; a lone dot's edge is ~5 pt from its center.
        edge = 0 if lo != hi else 5
        cost_side, spot = spec[m]
        cost = mf.money(hi) if lo == hi else mf.money(lo) + "–" + mf.money(hi)
        if cost_side == "a":
            label(ax, x, hi, 0, edge + COST_GAP, cost, c, COST_SIZE, "center", "bottom")
        else:
            label(ax, x, lo, 0, -edge - COST_GAP, cost, c, COST_SIZE, "center", "top")
        name_text = "(" + r["label"].replace(" (reasoning stage only)", " (RL step)") + ")"
        if isinstance(spot, str) and spot in ("a", "b"):
            sign = 1 if spot == "a" else -1
            dy = sign * (edge + (COST_GAP + LINE if cost_side == spot else GAP))
            label(ax, x, hi if spot == "a" else lo, 0, dy, name_text, c, MODEL_SIZE, "center",
                  "bottom" if spot == "a" else "top")
        else:
            anchor, dx, dy, ha, va = SPOT.get(spot, spot)
            y = {"mid": mid, "hi": hi, "lo": lo}[anchor]
            dy += {"hi": edge, "lo": -edge}.get(anchor, 0)
            label(ax, x, y, dx, dy, name_text, c, MODEL_SIZE, ha, va)
    ax.set_yscale("log")
    ax.set_ylim(100, 5e9)
    ticks = [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9]
    ax.set_yticks(ticks, ["$100", "$1k", "$10k", "$100k", "$1M", "$10M", "$100M", "$1B"])
    ax.minorticks_off()
    ax.set_xlim(2016.4, 2026.0)
    ax.set_xticks(range(2017, 2026))
    ax.grid(axis="y", color=mf.BORDER, lw=0.8)
    ax.set_axisbelow(True)
    for side in ("top", "right", "left", "bottom"):
        ax.spines[side].set_visible(side == "bottom")
    ax.spines["bottom"].set_color(mf.BORDER)
    ax.tick_params(colors=mf.MUTED, length=0)
    keys = [k for k in ("strubell", "reported", "estimate") if k in show]
    ax.legend([mf.LEGEND[k] for k in keys], [mf.LEGEND_TEXT[k] for k in keys], loc="upper left",
              frameon=False, fontsize=12, labelcolor=mf.MUTED, handler_map={tuple: HandlerTuple(ndivide=1)})
    ax.set_title("Compute cost to train one model", loc="left", fontsize=19, fontweight="bold", pad=14)
    fig.savefig(HERE / f"{name}.svg", transparent=True)
    plt.close(fig)


if __name__ == "__main__":
    data = mf.load()
    for name, spec in VARIANTS.items():
        frame(data, spec, name)
